/bin/bash -lc "python3 - <<'PY'
import json
x=json.load(open('runtime_context.json'))
for k,v in x['context'].items():
 if k=='history':
  for t in v:
   print(json.dumps({a:b for a,b in t.items() if a"'!='"'validation'})); print('VALIDATION',json.dumps(t.get('validation',{})))
 else: print(k,json.dumps(v,indent=2))
print('SCHEMA',json.dumps(x['study_schema'],indent=2))
PY"

