/bin/bash -lc "python3 - <<'PY'
import json
x=json.load(open('runtime_context.json')); c=x['context']
for k in c:
 if k not in ('history','trajectory_index'): print(k,json.dumps(c[k]))
print('TRIALS')
for t in c['history']:
 v=t.get('validation') or {}; print(t['id'],t['status'],'AUC',v.get('auc'),'wall',t.get('wall_seconds'),'train',t.get('train_seconds'),'params',t.get('parameters'),'infer',v.get('inference_seconds'), 'error',t.get('error'))
print('TRAJECTORY',json.dumps(c.get('trajectory_index'),indent=2))
PY"

